/**
 * FileExplorer Component - Main file and folder listing component
 * 
 * Responsibilities:
 * - Display folders and files in current directory
 * - Handle folder navigation
 * - Handle file downloads
 * - Show loading and error states
 * 
 * Import rules:
 * - Can import: hooks (useFiles, useFolders, useFolderNavigation)
 * - Can import: other components (FileItem, FolderItem, Breadcrumbs)
 * - Should NOT import: services, pages
 */

import React, { useRef, useState, useImperativeHandle, forwardRef, useEffect } from 'react';
import { useFiles } from '../../hooks/useFiles';
import { useFolders } from '../../hooks/useFolders';
import { useFolderNavigation } from '../../hooks/useFolderNavigation';
import { filesService, foldersService } from '../../services';
import Breadcrumbs from '../Breadcrumbs/Breadcrumbs';
import FolderItem from '../FolderItem/FolderItem';
import FileItem from '../FileItem/FileItem';

// Move/Copy Dialog Component
const MoveCopyDialog = ({ isOpen, onClose, onConfirm, mode, folders, currentFolderId }) => {
  const [selectedFolderId, setSelectedFolderId] = useState(null);

  if (!isOpen) return null;

  const handleConfirm = () => {
    if (selectedFolderId !== null) {
      onConfirm(selectedFolderId);
    }
  };

  return (
    <div className="dialog-overlay" onClick={onClose}>
      <div className="dialog-content" onClick={(e) => e.stopPropagation()}>
        <div className="dialog-header">
          <h3>{mode === 'move' ? 'Move to' : 'Copy to'}</h3>
          <button className="dialog-close" onClick={onClose}>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
              <path d="M19 6.41L17.59 5L12 10.59L6.41 5L5 6.41L10.59 12L5 17.59L6.41 19L12 13.41L17.59 19L19 17.59L13.41 12L19 6.41Z" fill="currentColor"/>
            </svg>
          </button>
        </div>
        <div className="dialog-body">
          <div className="folder-select-list">
            <button 
              className={`folder-select-item ${selectedFolderId === null ? 'selected' : ''}`}
              onClick={() => setSelectedFolderId(null)}
            >
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                <path d="M10 4H4C2.9 4 2.01 4.9 2.01 6L2 18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V8C22 6.9 21.1 6 20 6H12L10 4Z" fill="currentColor"/>
              </svg>
              <span>My Drive (Root)</span>
            </button>
            {folders.filter(f => f.id !== currentFolderId).map(folder => (
              <button
                key={folder.id}
                className={`folder-select-item ${selectedFolderId === folder.id ? 'selected' : ''}`}
                onClick={() => setSelectedFolderId(folder.id)}
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                  <path d="M10 4H4C2.9 4 2.01 4.9 2.01 6L2 18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V8C22 6.9 21.1 6 20 6H12L10 4Z" fill="currentColor"/>
                </svg>
                <span>{folder.name}</span>
              </button>
            ))}
          </div>
        </div>
        <div className="dialog-footer">
          <button className="btn-secondary" onClick={onClose}>Cancel</button>
          <button className="btn-primary" onClick={handleConfirm} disabled={selectedFolderId === null && currentFolderId !== null}>
            {mode === 'move' ? 'Move' : 'Copy'}
          </button>
        </div>
      </div>
    </div>
  );
};

// Helper to get/set view preference
const getViewPreference = () => {
  const saved = localStorage.getItem('fileViewMode');
  return saved === 'grid' ? 'grid' : 'list';
};

const setViewPreference = (view) => {
  localStorage.setItem('fileViewMode', view);
};

const FileExplorer = forwardRef((props, ref) => {
  const { currentFolderId, breadcrumbs, navigateToFolder, navigateBack, navigateToRoot } = useFolderNavigation();
  const fileInputRef = useRef(null);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [viewMode, setViewMode] = useState(getViewPreference);
  const [selectedItems, setSelectedItems] = useState(new Set());
  const [showMoveDialog, setShowMoveDialog] = useState(false);
  const [showCopyDialog, setShowCopyDialog] = useState(false);
  const [moveCopyTarget, setMoveCopyTarget] = useState(null);
  const [moveCopyItems, setMoveCopyItems] = useState([]);
  const [activeFilter, setActiveFilter] = useState('all');
  
  const { folders, loading: foldersLoading, createFolder, refetch: refetchFolders } = useFolders(currentFolderId);
  const { files, loading: filesLoading, downloadFile, refetch: refetchFiles } = useFiles(currentFolderId);

  const handleCreateFolder = async () => {
    const folderName = prompt('Enter folder name:');
    if (folderName && folderName.trim()) {
      try {
        await createFolder(folderName.trim());
        refetchFolders();
      } catch (error) {
        alert(`Failed to create folder: ${error.message}`);
      }
    }
  };

  const triggerUpload = () => {
    fileInputRef.current?.click();
  };

  // Expose methods to parent via ref
  useImperativeHandle(ref, () => ({
    createFolder: handleCreateFolder,
    triggerUpload: triggerUpload,
  }));

  const handleUploadClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileUpload = async (e) => {
    const filesToUpload = Array.from(e.target.files || []);
    if (filesToUpload.length === 0) {
      // Reset input if no files selected
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
      return;
    }

    setUploading(true);
    setUploadProgress(0);

    const uploadErrors = [];

    try {
      // Upload files sequentially
      for (let i = 0; i < filesToUpload.length; i++) {
        const file = filesToUpload[i];
        try {
          console.log(`Uploading file: ${file.name} to folder: ${currentFolderId || 'root'}`);
          await filesService.uploadFile(file, currentFolderId);
          setUploadProgress(((i + 1) / filesToUpload.length) * 100);
          console.log(`Successfully uploaded: ${file.name}`);
        } catch (error) {
          console.error(`Failed to upload ${file.name}:`, error);
          uploadErrors.push({ fileName: file.name, error: error.message || 'Upload failed' });
          // Continue with other files even if one fails
        }
      }

      // Show error summary if any files failed
      if (uploadErrors.length > 0) {
        const errorMessage = uploadErrors.length === filesToUpload.length
          ? `Failed to upload all files:\n${uploadErrors.map(e => `- ${e.fileName}: ${e.error}`).join('\n')}`
          : `Some files failed to upload:\n${uploadErrors.map(e => `- ${e.fileName}: ${e.error}`).join('\n')}`;
        window.alert(errorMessage);
      } else if (filesToUpload.length > 0) {
        // Show success message
        console.log('All files uploaded successfully');
      }

      // Wait a bit for backend to process, then refresh
      setTimeout(async () => {
        try {
          await refetchFiles();
          await refetchFolders();
          console.log('Files and folders refreshed');
        } catch (error) {
          console.error('Error refreshing files:', error);
        }
      }, 1000);
    } catch (error) {
      console.error('Upload error:', error);
      window.alert(`Failed to upload: ${error.message || 'Unknown error'}`);
    } finally {
      setUploading(false);
      setUploadProgress(0);
      // Reset input after upload completes
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    }
  };

  const handleFolderClick = (folderId, folderName) => {
    navigateToFolder(folderId, folderName);
  };

  const handleBreadcrumbClick = (folderId) => {
    navigateBack(folderId);
  };

  const handleFileDownload = async (fileId) => {
    try {
      await downloadFile(fileId);
    } catch (error) {
      alert(`Failed to download: ${error.message}`);
    }
  };

  const handleFileDelete = async (fileId) => {
    if (window.confirm('Move this file to trash?')) {
      try {
        await filesService.deleteFile(fileId);
        await refetchFiles();
      } catch (error) {
        alert(`Failed to delete: ${error.message}`);
      }
    }
  };

  const handleFolderDelete = async (folderId) => {
    if (window.confirm('Move this folder to trash?')) {
      try {
        await foldersService.deleteFolder(folderId);
        await refetchFolders();
      } catch (error) {
        alert(`Failed to delete: ${error.message}`);
      }
    }
  };

  const handleViewToggle = (mode) => {
    setViewMode(mode);
    setViewPreference(mode);
  };

  // Selection handlers
  const handleItemSelect = (itemId, itemType) => {
    const key = `${itemType}|${itemId}`;
    setSelectedItems(prev => {
      const newSet = new Set(prev);
      if (newSet.has(key)) {
        newSet.delete(key);
      } else {
        newSet.add(key);
      }
      return newSet;
    });
  };

  const handleSelectAll = () => {
    const allKeys = [
      ...foldersArray.map(f => `folder|${f.id}`),
      ...filesArray.map(f => `file|${f.id}`)
    ];
    setSelectedItems(new Set(allKeys));
  };

  const handleDeselectAll = () => {
    setSelectedItems(new Set());
  };

  const isItemSelected = (itemId, itemType) => {
    return selectedItems.has(`${itemType}|${itemId}`);
  };

  // Action handlers
  const handleShare = async (itemId, itemType) => {
    try {
      if (itemType === 'file') {
        await filesService.shareFile(itemId);
        window.alert('File shared successfully!');
      } else {
        await foldersService.shareFolder(itemId);
        window.alert('Folder shared successfully!');
      }
    } catch (error) {
      window.alert(`Failed to share: ${error.message}`);
    }
  };

  const handleCopyLink = async (itemId, itemType) => {
    try {
      let link;
      if (itemType === 'file') {
        const response = await filesService.getShareLink(itemId);
        link = response?.data?.link || response?.link || `${window.location.origin}/share/file/${itemId}`;
      } else {
        const response = await foldersService.getShareLink(itemId);
        link = response?.data?.link || response?.link || `${window.location.origin}/share/folder/${itemId}`;
      }
      
      await navigator.clipboard.writeText(link);
      window.alert('Link copied to clipboard!');
    } catch (error) {
      window.alert(`Failed to copy link: ${error.message}`);
    }
  };

  const handleRename = async (itemId, itemType, currentName) => {
    const newName = window.prompt('Enter new name:', currentName);
    if (!newName || newName.trim() === currentName) return;

    try {
      if (itemType === 'file') {
        await filesService.renameFile(itemId, newName.trim());
      } else {
        await foldersService.renameFolder(itemId, newName.trim());
      }
      await refetchFiles();
      await refetchFolders();
    } catch (error) {
      window.alert(`Failed to rename: ${error.message}`);
    }
  };

  const handleMove = (itemId, itemType) => {
    setMoveCopyItems([{ id: itemId, type: itemType }]);
    setShowMoveDialog(true);
  };

  const handleCopy = (itemId, itemType) => {
    setMoveCopyItems([{ id: itemId, type: itemType }]);
    setShowCopyDialog(true);
  };

  const handleMoveSelected = () => {
    const items = Array.from(selectedItems).map(key => {
      const [type, ...idParts] = key.split('|');
      const id = idParts.join('|');
      return { id, type: type === 'folder' ? 'folder' : 'file' };
    });
    setMoveCopyItems(items);
    setShowMoveDialog(true);
  };

  const handleCopySelected = () => {
    const items = Array.from(selectedItems).map(key => {
      const [type, ...idParts] = key.split('|');
      const id = idParts.join('|');
      return { id, type: type === 'folder' ? 'folder' : 'file' };
    });
    setMoveCopyItems(items);
    setShowCopyDialog(true);
  };

  const executeMove = async (targetFolderId) => {
    try {
      for (const item of moveCopyItems) {
        if (item.type === 'file') {
          await filesService.moveFile(item.id, targetFolderId);
        } else {
          await foldersService.moveFolder(item.id, targetFolderId);
        }
      }
      await refetchFiles();
      await refetchFolders();
      setShowMoveDialog(false);
      setSelectedItems(new Set());
      window.alert('Items moved successfully!');
    } catch (error) {
      window.alert(`Failed to move: ${error.message}`);
    }
  };

  const executeCopy = async (targetFolderId) => {
    try {
      for (const item of moveCopyItems) {
        if (item.type === 'file') {
          await filesService.copyFile(item.id, targetFolderId);
        } else {
          await foldersService.copyFolder(item.id, targetFolderId);
        }
      }
      await refetchFiles();
      await refetchFolders();
      setShowCopyDialog(false);
      setSelectedItems(new Set());
      window.alert('Items copied successfully!');
    } catch (error) {
      window.alert(`Failed to copy: ${error.message}`);
    }
  };

  const handleDeleteSelected = async () => {
    if (!window.confirm(`Delete ${selectedItems.size} item(s)?`)) return;

    try {
      for (const key of selectedItems) {
        const [type, ...idParts] = key.split('|');
        const id = idParts.join('|');
        if (type === 'file') {
          await filesService.deleteFile(id);
        } else {
          await foldersService.deleteFolder(id);
        }
      }
      await refetchFiles();
      await refetchFolders();
      setSelectedItems(new Set());
    } catch (error) {
      window.alert(`Failed to delete: ${error.message}`);
    }
  };

  const handleDownloadSelected = async () => {
    try {
      for (const key of selectedItems) {
        const [type, ...idParts] = key.split('|');
        const id = idParts.join('|');
        if (type === 'file') {
          await downloadFile(id);
        }
      }
    } catch (error) {
      window.alert(`Failed to download: ${error.message}`);
    }
  };

  const handleShareSelected = async () => {
    try {
      for (const key of selectedItems) {
        const [type, ...idParts] = key.split('|');
        const id = idParts.join('|');
        await handleShare(id, type);
      }
    } catch (error) {
      window.alert(`Failed to share: ${error.message}`);
    }
  };

  const handleCopyLinkSelected = async () => {
    try {
      const links = [];
      for (const key of selectedItems) {
        const [type, ...idParts] = key.split('|');
        const id = idParts.join('|');
        let link;
        if (type === 'file') {
          const response = await filesService.getShareLink(id);
          link = response?.data?.link || response?.link || `${window.location.origin}/share/file/${id}`;
        } else {
          const response = await foldersService.getShareLink(id);
          link = response?.data?.link || response?.link || `${window.location.origin}/share/folder/${id}`;
        }
        links.push(link);
      }
      await navigator.clipboard.writeText(links.join('\n'));
      window.alert('Links copied to clipboard!');
    } catch (error) {
      window.alert(`Failed to copy links: ${error.message}`);
    }
  };

  if (foldersLoading || filesLoading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>Loading...</p>
      </div>
    );
  }

  // Ensure folders and files are arrays before mapping
  const foldersArray = Array.isArray(folders) ? folders : [];
  const filesArray = Array.isArray(files) ? files : [];

  // Filter items based on active filter
  const getFilteredItems = () => {
    let filtered = [
      ...foldersArray.map(f => ({ ...f, type: 'folder' })),
      ...filesArray.map(f => ({ ...f, type: 'file' }))
    ];

    if (activeFilter === 'recent') {
      filtered = filtered.sort((a, b) => {
        const aDate = new Date(a.updated_at || a.created_at || 0);
        const bDate = new Date(b.updated_at || b.created_at || 0);
        return bDate - aDate;
      });
    } else if (activeFilter !== 'all') {
      filtered = filtered.filter(item => {
        if (item.type === 'folder') return false;
        const mimeType = (item.mime_type || item.mimeType || '').toLowerCase();
        const fileName = (item.name || '').toLowerCase();
        
        switch (activeFilter) {
          case 'word':
            return mimeType.includes('word') || mimeType.includes('document') || fileName.endsWith('.doc') || fileName.endsWith('.docx');
          case 'excel':
            return mimeType.includes('excel') || mimeType.includes('spreadsheet') || fileName.endsWith('.xls') || fileName.endsWith('.xlsx');
          case 'powerpoint':
            return mimeType.includes('powerpoint') || mimeType.includes('presentation') || fileName.endsWith('.ppt') || fileName.endsWith('.pptx');
          default:
            return true;
        }
      });
    } else {
      filtered = filtered.sort((a, b) => {
        if (a.type !== b.type) return a.type === 'folder' ? -1 : 1;
        return a.name.localeCompare(b.name);
      });
    }

    return filtered;
  };

  const allItems = getFilteredItems();

  return (
    <div className="file-explorer">
      <div className="file-explorer-header">
        <h1 className="page-title">My files</h1>
        <div className="page-controls">
          <button className="page-control-btn" title="Sort">
            <span>Sort</span>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none">
              <path d="M7 10L12 15L17 10H7Z" fill="currentColor"/>
            </svg>
          </button>
          <div className="view-toggle">
            <button
              className={`view-toggle-btn ${viewMode === 'list' ? 'active' : ''}`}
              onClick={() => handleViewToggle('list')}
              title="List view"
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                <path d="M3 13H5V11H3V13ZM3 17H5V15H3V17ZM3 9H5V7H3V9ZM7 13H21V11H7V13ZM7 17H21V15H7V17ZM7 7V9H21V7H7Z" fill="currentColor"/>
              </svg>
            </button>
            <button
              className={`view-toggle-btn ${viewMode === 'grid' ? 'active' : ''}`}
              onClick={() => handleViewToggle('grid')}
              title="Grid view"
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                <path d="M3 3V11H11V3H3ZM9 9H5V5H9V9ZM3 13V21H11V13H3ZM9 19H5V15H9V19ZM13 3V11H21V3H13ZM19 9H15V5H19V9ZM13 13V21H21V13H13ZM19 19H15V15H19V19Z" fill="currentColor"/>
              </svg>
            </button>
          </div>
          <button className="page-control-btn" title="Details">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
              <path d="M3 3H21V5H3V3ZM3 7H21V9H3V7ZM3 11H21V13H3V11ZM3 15H21V17H3V15ZM3 19H21V21H3V19Z" fill="currentColor"/>
            </svg>
          </button>
        </div>
      </div>
      <div className="file-explorer-toolbar">
        <Breadcrumbs breadcrumbs={breadcrumbs} onNavigate={handleBreadcrumbClick} />
        <div className="toolbar-actions">
          <div className="view-toggle">
            <button
              className={`view-toggle-btn ${viewMode === 'list' ? 'active' : ''}`}
              onClick={() => handleViewToggle('list')}
              title="List view"
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                <path d="M3 13H5V11H3V13ZM3 17H5V15H3V17ZM3 9H5V7H3V9ZM7 13H21V11H7V13ZM7 17H21V15H7V17ZM7 7V9H21V7H7Z" fill="currentColor"/>
              </svg>
            </button>
            <button
              className={`view-toggle-btn ${viewMode === 'grid' ? 'active' : ''}`}
              onClick={() => handleViewToggle('grid')}
              title="Grid view"
            >
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                <path d="M3 3V11H11V3H3ZM9 9H5V5H9V9ZM3 13V21H11V13H3ZM9 19H5V15H9V19ZM13 3V11H21V3H13ZM19 9H15V5H19V9ZM13 13V21H21V13H13ZM19 19H15V15H19V19Z" fill="currentColor"/>
              </svg>
            </button>
          </div>
          <button 
            className="btn-upload" 
            onClick={handleUploadClick} 
            title="Upload File"
            disabled={uploading}
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
              <path d="M19 12V19H5V12H3V19C3 20.1 3.9 21 5 21H19C20.1 21 21 20.1 21 19V12H19ZM13 12.67L15.59 10.09L17 11.5L12 16.5L7 11.5L8.41 10.09L11 12.67V3H13V12.67Z" fill="currentColor"/>
            </svg>
            {uploading ? `Uploading... ${Math.round(uploadProgress)}%` : 'Upload'}
          </button>
          <input
            ref={fileInputRef}
            type="file"
            style={{ display: 'none' }}
            onChange={handleFileUpload}
            onClick={(e) => {
              // Reset value to allow selecting the same file again
              e.target.value = '';
            }}
            multiple={true}
            disabled={uploading}
            accept="*/*"
          />
          <button 
            className="btn-create-folder" 
            onClick={handleCreateFolder} 
            title="New Folder"
            disabled={uploading}
          >
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
              <path d="M10 4H4C2.9 4 2.01 4.9 2.01 6L2 18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V8C22 6.9 21.1 6 20 6H12L10 4Z" fill="currentColor"/>
            </svg>
            New Folder
          </button>
        </div>
      </div>
      
      {allItems.length === 0 ? (
        <div className="empty-state">
          <div className="empty-state-content">
            <div className="empty-illustration">
              <svg width="200" height="200" viewBox="0 0 200 200" fill="none" xmlns="http://www.w3.org/2000/svg">
                <defs>
                  <linearGradient id="folderGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                    <stop offset="0%" style={{stopColor: '#FFA726', stopOpacity: 1}} />
                    <stop offset="100%" style={{stopColor: '#FB8C00', stopOpacity: 1}} />
                  </linearGradient>
                </defs>
                <path d="M40 50L60 30H140L160 50V170H40V50Z" fill="url(#folderGradient)" opacity="0.9"/>
                <path d="M40 50H160V60H40V50Z" fill="#FFB74D"/>
                <path d="M50 70H150V80H50V70Z" fill="rgba(255,255,255,0.3)"/>
                <path d="M50 90H130V100H50V90Z" fill="rgba(255,255,255,0.2)"/>
                <circle cx="100" cy="130" r="15" fill="rgba(255,255,255,0.4)"/>
                <path d="M95 130L100 125L105 130M100 125V135" stroke="rgba(255,255,255,0.6)" strokeWidth="2" fill="none"/>
              </svg>
            </div>
            <h2 className="empty-title">This folder is empty</h2>
            <p className="empty-hint">Get started by uploading your first file or creating a new folder</p>
            <div className="empty-actions">
              <button 
                className="empty-action-btn primary" 
                onClick={handleUploadClick}
                disabled={uploading}
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                  <path d="M19 12V19H5V12H3V19C3 20.1 3.9 21 5 21H19C20.1 21 21 20.1 21 19V12H19ZM13 12.67L15.59 10.09L17 11.5L12 16.5L7 11.5L8.41 10.09L11 12.67V3H13V12.67Z" fill="currentColor"/>
                </svg>
                <span>Upload Files</span>
              </button>
              <button 
                className="empty-action-btn secondary" 
                onClick={handleCreateFolder}
                disabled={uploading}
              >
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                  <path d="M10 4H4C2.9 4 2.01 4.9 2.01 6L2 18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V8C22 6.9 21.1 6 20 6H12L10 4Z" fill="currentColor"/>
                </svg>
                <span>Create Folder</span>
              </button>
            </div>
          </div>
        </div>
      ) : viewMode === 'list' ? (
        <div className="file-grid file-grid-list">
          {selectedItems.size > 0 && (
            <div className="selection-toolbar">
              <div className="selection-info">
                <button className="selection-close" onClick={handleDeselectAll}>
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                    <path d="M19 6.41L17.59 5L12 10.59L6.41 5L5 6.41L10.59 12L5 17.59L6.41 19L12 13.41L17.59 19L19 17.59L13.41 12L19 6.41Z" fill="currentColor"/>
                  </svg>
                </button>
                <span className="selection-count">{selectedItems.size} selected</span>
              </div>
              <div className="selection-actions">
                <button className="selection-action-btn" onClick={handleShareSelected} title="Share">
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                    <path d="M18 16.08C17.24 16.08 16.56 16.38 16.04 16.85L8.91 12.7C8.96 12.47 9 12.24 9 12C9 11.76 8.96 11.53 8.91 11.3L15.96 7.19C16.5 7.69 17.21 8 18 8C19.66 8 21 6.66 21 5C21 3.34 19.66 2 18 2C16.34 2 15 3.34 15 5C15 5.24 15.04 5.47 15.09 5.7L8.04 9.81C7.5 9.31 6.79 9 6 9C4.34 9 3 10.34 3 12C3 13.66 4.34 15 6 15C6.79 15 7.5 14.69 8.04 14.19L15.16 18.34C15.11 18.55 15.08 18.77 15.08 19C15.08 20.61 16.39 21.92 18 21.92C19.61 21.92 20.92 20.61 20.92 19C20.92 17.39 19.61 16.08 18 16.08Z" fill="currentColor"/>
                  </svg>
                </button>
                <button className="selection-action-btn" onClick={handleCopyLinkSelected} title="Copy link">
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                    <path d="M3.9 12C3.9 10.29 5.29 8.9 7 8.9H11V7H7C4.24 7 2 9.24 2 12C2 14.76 4.24 17 7 17H11V15.1H7C5.29 15.1 3.9 13.71 3.9 12ZM8 13H16V11H8V13ZM17 7H13V8.9H17C18.71 8.9 20.1 10.29 20.1 12C20.1 13.71 18.71 15.1 17 15.1H13V17H17C19.76 17 22 14.76 22 12C22 9.24 19.76 7 17 7Z" fill="currentColor"/>
                  </svg>
                </button>
                <button className="selection-action-btn" onClick={handleDeleteSelected} title="Delete">
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                    <path d="M6 19C6 20.1 6.9 21 8 21H16C17.1 21 18 20.1 18 19V7H6V19ZM19 4H15.5L14.5 3H9.5L8.5 4H5V6H19V4Z" fill="currentColor"/>
                  </svg>
                </button>
                <button className="selection-action-btn" onClick={handleDownloadSelected} title="Download">
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                    <path d="M19 12V19H5V12H3V19C3 20.1 3.9 21 5 21H19C20.1 21 21 20.1 21 19V12H19ZM13 12.67L15.59 10.09L17 11.5L12 16.5L7 11.5L8.41 10.09L11 12.67V3H13V12.67Z" fill="currentColor"/>
                  </svg>
                </button>
                <button className="selection-action-btn" onClick={handleMoveSelected} title="Move to">
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                    <path d="M10 4H4C2.9 4 2.01 4.9 2.01 6L2 18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V8C22 6.9 21.1 6 20 6H12L10 4Z" fill="currentColor"/>
                    <path d="M16 13L13 10V12H9V14H13V16L16 13Z" fill="currentColor"/>
                  </svg>
                </button>
                <button className="selection-action-btn" onClick={handleCopySelected} title="Copy to">
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                    <path d="M10 4H4C2.9 4 2.01 4.9 2.01 6L2 18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V8C22 6.9 21.1 6 20 6H12L10 4Z" fill="currentColor"/>
                    <path d="M16 13L13 10V12H9V14H13V16L16 13Z" fill="currentColor"/>
                    <path d="M20 2H10C8.9 2 8 2.9 8 4V6H10V4H20V14H18V16H20C21.1 16 22 15.1 22 14V4C22 2.9 21.1 2 20 2Z" fill="currentColor"/>
                  </svg>
                </button>
              </div>
            </div>
          )}
          <div className="file-grid-header">
            <div className="file-header-checkbox">
              <input
                type="checkbox"
                checked={selectedItems.size > 0 && selectedItems.size === allItems.length}
                onChange={(e) => {
                  if (e.target.checked) {
                    handleSelectAll();
                  } else {
                    handleDeselectAll();
                  }
                }}
              />
            </div>
            <div className="file-header-name">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none">
                <path d="M10 4H4C2.9 4 2.01 4.9 2.01 6L2 18C2 19.1 2.9 20 4 20H20C21.1 20 22 19.1 22 18V8C22 6.9 21.1 6 20 6H12L10 4Z" fill="currentColor"/>
              </svg>
              Name
            </div>
            <div className="file-header-modified">Modified</div>
            <div className="file-header-size">File size</div>
            <div className="file-header-sharing">Sharing</div>
            <div className="file-header-actions"></div>
          </div>
          {allItems.map((item) => 
            item.type === 'folder' ? (
              <FolderItem
                key={item.id}
                folder={item}
                onNavigate={handleFolderClick}
                onDelete={handleFolderDelete}
                viewMode="list"
                isSelected={isItemSelected(item.id, 'folder')}
                onSelect={handleItemSelect}
                onShare={handleShare}
                onCopyLink={handleCopyLink}
                onRename={handleRename}
                onMove={handleMove}
                onCopy={handleCopy}
                onManageAccess={(id, type) => window.alert('Manage access feature coming soon!')}
              />
            ) : (
              <FileItem
                key={item.id}
                file={item}
                onDownload={handleFileDownload}
                onDelete={handleFileDelete}
                viewMode="list"
                isSelected={isItemSelected(item.id, 'file')}
                onSelect={handleItemSelect}
                onShare={handleShare}
                onCopyLink={handleCopyLink}
                onRename={handleRename}
                onMove={handleMove}
                onCopy={handleCopy}
                onManageAccess={(id, type) => window.alert('Manage access feature coming soon!')}
              />
            )
          )}
        </div>
      ) : (
        <div className="file-grid file-grid-grid">
          {allItems.map((item) => 
            item.type === 'folder' ? (
              <FolderItem
                key={item.id}
                folder={item}
                onNavigate={handleFolderClick}
                onDelete={handleFolderDelete}
                viewMode="grid"
              />
            ) : (
              <FileItem
                key={item.id}
                file={item}
                onDownload={handleFileDownload}
                onDelete={handleFileDelete}
                viewMode="grid"
              />
            )
          )}
        </div>
      )}
      <MoveCopyDialog
        isOpen={showMoveDialog}
        onClose={() => setShowMoveDialog(false)}
        onConfirm={executeMove}
        mode="move"
        folders={foldersArray}
        currentFolderId={currentFolderId}
      />
      <MoveCopyDialog
        isOpen={showCopyDialog}
        onClose={() => setShowCopyDialog(false)}
        onConfirm={executeCopy}
        mode="copy"
        folders={foldersArray}
        currentFolderId={currentFolderId}
      />
    </div>
  );
});

FileExplorer.displayName = 'FileExplorer';

export default FileExplorer;
